create table if not exists public.sale_returns(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,sale_id bigint not null references public.sales(id) on delete restrict,return_number text not null,return_date timestamptz not null default now,status text not null default 'posted',reason text,refund_amount numeric(14,2) not null default 0,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,return_number));
create table if not exists public.sale_return_items(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,sale_return_id bigint not null references public.sale_returns(id) on delete cascade,sale_item_id bigint references public.sale_items(id) on delete set null,product_id bigint not null references public.products(id),stock_id bigint references public.stocks(id) on delete set null,quantity integer not null,refund_amount numeric(14,2) not null default 0,batch_no text,expire_date date,created_at timestamptz not null default now());
create table if not exists public.purchase_returns(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,purchase_id bigint not null references public.purchases(id) on delete restrict,return_number text not null,return_date timestamptz not null default now(),status text not null default 'posted',reason text,refund_amount numeric(14,2) not null default 0,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,return_number));
create table if not exists public.purchase_return_items(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,purchase_return_id bigint not null references public.purchase_returns(id) on delete cascade,purchase_item_id bigint references public.purchase_items(id) on delete set null,product_id bigint not null references public.products(id),stock_id bigint references public.stocks(id) on delete set null,quantity integer not null,refund_amount numeric(14,2) not null default 0,batch_no text,expire_date date,created_at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['sale_returns','sale_return_items','purchase_returns','purchase_return_items'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); execute format('create policy %I on public.%I for all to authenticated using (business_id=(select private.current_business_id())) with check (business_id=(select private.current_business_id()))',t||'_tenant',t); end loop;end$$;
create or replace function private.enforce_return_business() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin if new.quantity<=0 then raise exception 'quantity must be positive'; end if; if new.product_id is null then raise exception 'product required'; end if; if new.stock_id is not null and not exists(select 1 from stocks s where s.id=new.stock_id and s.business_id=new.business_id and s.product_id=new.product_id) then raise exception 'stock does not belong to business/product'; end if; return new; end$$;
revoke all on function private.enforce_return_business() from public,anon,authenticated;
create trigger trg_sale_return_item_integrity before insert or update on public.sale_return_items for each row execute function private.enforce_return_business();
create trigger trg_purchase_return_item_integrity before insert or update on public.purchase_return_items for each row execute function private.enforce_return_business();